namespace XboxGamingBar
{
    public sealed partial class GamingWidget
    {
        // Policy definitions: Microsoft PERFBOOSTMODE and SCHEDPOLICY documentation.
        private const string OnexBoostHelp = "Разрешает процессору временно повышать частоту, когда нужны дополнительные вычисления. Это не увеличивает установленный TDP.\n\nDisabled — без ускорения выше номинального уровня. Enabled — Windows выбирает нужный уровень. Aggressive — более активный запрос производительности. Efficient варианты учитывают экономию энергии; некоторые режимы на конкретном процессоре могут работать одинаково. Варианты at guaranteed меняют способ запроса производительности выше гарантированного уровня. Реальное поведение зависит от процессора и Windows.\n\nПример: если в игре процессор сильно греется, попробуй Disabled на батарее и сравни температуру и FPS. Для тяжёлой игры от зарядки можно сравнить Enabled и Aggressive.";
        private const string OnexCoreHelp = "Выбирает, каким ядрам Windows отдаёт предпочтение: быстрым P-ядрам или экономичным E-ядрам.\n\nAll cores — доступны все. Only performance/efficiency — ограничение соответствующим типом. Prefer — предпочтение без такого жёсткого ограничения. Automatic — Windows выбирает с учётом задачи. Здесь одинаковая политика задаётся для коротких и длинных потоков.\n\nПример: для игры сравни Automatic и Prefer performance cores. Only efficiency cores может уменьшить производительность игры; это скорее режим для лёгкой работы. Это не изменение числа физических ядер.";
        private const string OnexFrequencyHelp = "Задаёт максимальную частоту CPU через OneXConsole. Выключенный переключатель означает Auto: процессор сам выбирает частоту. Включённый — действует выбранный потолок в МГц. Это потолок, а не обещание постоянной частоты.\n\nПример: 2500 MHz = максимум 2,5 ГГц. В лёгкой игре это может уменьшить нагрев; в игре, которой не хватает CPU, может снизить FPS. Сравни при одном и том же TDP. Auto убирает этот дополнительный предел.";
        private const string OnexMaskHelp = "Дополнительная системная настройка OneXConsole для работы Windows с разными типами ядер. Она меняет OEM-параметр планирования и начинает действовать после перезапуска Windows. Это отдельная настройка от Core preference; автоматического прироста FPS она не гарантирует.\n\nПример: если конкретная игра работает неровно, можно сравнить её до и после включения с перезапуском, сохранив тот же TDP и режим Boost. Для возврата выключи опцию и снова перезапусти Windows.";
    }
}
